# Attorney signature — set ATTORNEY_SIGNATURE_B64 in Railway environment variables
import os as _os
SIGNATURE_B64 = _os.environ.get('ATTORNEY_SIGNATURE_B64', '')

def _sig_img():
    """Return a ReportLab Image element from the attorney signature base64."""
    import io as _io
    try:
        raw = __import__('base64').b64decode(SIGNATURE_B64)
        # Use PIL to open and re-encode as PNG for reliable ReportLab rendering
        from PIL import Image as _PILImage
        pil_img = _PILImage.open(_io.BytesIO(raw)).convert('RGBA')
        png_buf = _io.BytesIO()
        pil_img.save(png_buf, format='PNG')
        png_buf.seek(0)
        img = RLImage(png_buf, width=2.0*72, height=0.75*72)
        img.hAlign = 'LEFT'
        return img
    except Exception as _e:
        import logging as _logging
        _logging.getLogger(__name__).warning(f'_sig_img failed: {_e}')
        from reportlab.platypus import Spacer
        return Spacer(1, 0.4*72)

def generate_documents(motion_type, data):
    doc_info = DOCS.get(motion_type)
    if not doc_info:
        raise ValueError(f'Unknown motion type: {motion_type}')

